#!/usr/bin/env bash
set -euo pipefail
umask 077

# Generated by VM startup; contains configuration, never database passwords.
source /etc/datamonitor/deploy.env
MODE="${1:---update}"
case "$MODE" in
  --boot) ;;
  --update)
    git -C "$APP_DIR" remote set-url origin "$REPO_URL"
    git -C "$APP_DIR" fetch origin "$REPO_REF"
    git -C "$APP_DIR" checkout --detach FETCH_HEAD
    printf '%s\n' "$REPO_URL $REPO_REF" > /etc/datamonitor/source
    # Re-enter the deployment script from the selected release.
    exec bash "$APP_DIR/gcp-terra/scripts/deploy.sh" --boot
    ;;
  *) echo 'Usage: deploy.sh [--boot|--update]' >&2; exit 1 ;;
esac

SCRIPT_DIR="$APP_DIR/gcp-terra/scripts"
bash "$SCRIPT_DIR/install-docker.sh"
REVISION="$(git -C "$APP_DIR" rev-parse HEAD):$SERVICE_ROLE"
install -d -m 700 /var/lib/datamonitor
export BUILD_IMAGES=false
if [[ ! -f /var/lib/datamonitor/deployed-revision ]] || [[ "$(cat /var/lib/datamonitor/deployed-revision)" != "$REVISION" ]]; then
  BUILD_IMAGES=true
fi
bash "$SCRIPT_DIR/start-service.sh"
printf '%s\n' "$REVISION" > /var/lib/datamonitor/deployed-revision
